xm20 N006 Vm N008 0 sky130_fd_pr__nfet_01v8 w={W_xm20} l={L_xm20}

* Output Stage
xm21 vom vodp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm21} l={L_xm21}
xm22 N010 vodm VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm22} l={L_xm22}
xm23 vom N010 0 0 sky130_fd_pr__nfet_01v8 w={W_xm23} l={L_xm23}
xm24 N010 N010 0 0 sky130_fd_pr__nfet_01v8 w={W_xm24} l={L_xm24}
C1 vom ncr 5e-14
xm25 vop vodm VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm25} l={L_xm25}
xm26 N009 vodp VDD VDD sky130_fd_pr__pfet_01v8 w={W_xm26} l={L_xm26}
xm27 vop N009 0 0 sky130_fd_pr__nfet_01v8 w={W_xm27} l={L_xm27}
xm28 N009 N009 0 0 sky130_fd_pr__nfet_01v8 w={W_xm28} l={L_xm28}
C2 vop ncl 5e-14

* Closed-loop Feedback (Fig. 26.24)
R1 vop vm 20000.0
R2 vm vip 20000.0
R3 vom vp 20000.0
R4 vp vim 20000.0
C3 vom 0 2.5e-13
C4 vop 0 2.5e-13

* Control Block for ngspice
.control
* Operating point analysis
op
let idd_total = -i(VDD)
let p_diss = idd_total * 1.8
print idd_total
print p_diss

* Transient step response analysis (Fig. 26.24)
tran 0.05n 90n 0n
let vod = v(vop) - v(vom)
let vid = v(vip) - v(vim)

* Measure Slew Rate on rising edge of vod around 15ns transition
meas tran v_max max vod from=10n to=20n
meas tran v_min min vod from=10n to=20n
meas tran t_10 when vod=-0.3 rise=1
meas tran t_90 when vod=0.3 rise=1
let sr = (0.3 - (-0.3)) / (t_90 - t_10) / 1e6
print sr

* Settling time measurement
meas tran t_settle trig vid val=0 rise=1 targ vod val=0.39 rise=1
print t_settle

* Closed-loop swing and gain
meas tran vod_peak max vod from=70n to=90n
meas tran vid_peak max vid from=70n to=90n
let cl_gain = vod_peak / vid_peak
print cl_gain

quit
.endc
.end

